command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-20k-browse --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "5eb0fbb50c627a736e8e6ca2bb4d9793ebad33ea") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-20k-browse origin/work/large-folder-20k-browse
if ($LASTEXITCODE -ne 0) { throw "checkout harness fix failed" }
if ((git rev-parse HEAD).Trim() -ne "f48b7866fc7255765b068d9349fb57968f47473d") { throw "candidate mismatch" }
$changedProduct = git diff --name-only 924a035e244fb547662bedb7094f45b543396a36..HEAD -- app/winui src/base
if ($LASTEXITCODE -ne 0) { throw "product diff check failed" }
if ($changedProduct) { throw "harness-only resume unexpectedly changed product files: $changedProduct" }
if (!(Test-Path -LiteralPath "out\winui\Release\flyExplorer.exe")) { throw "accepted candidate Release binary missing" }

python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 20500 --configuration Release --browse-over-complete-model
if ($LASTEXITCODE -ne 0) { throw "browse-over-20k GUI/visual resume failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_OVER_20K_GUI_RESUME_PASS"
